/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for p in sorted(Path('/docs').glob('*.txt')):
 s=p.read_text(); lines=s.splitlines(); page='?'; hits=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'Nevada',l,re.I):
   hits.append((page,' '.join(lines[max(0,i-2):i+3])))
 print(p.name[:-4], 'Nevada mentions:',len(hits))
 for page,t in hits:
  if re.search(r'govern|laws|constru',t,re.I): print('PAGE',page,t)
PY"

